        "testata": "Limes",
        "lingua_originale": "it",
        "titolo_orig": "Xi riceve Putin in Cina e altre notizie interessanti",
        "testo_it": "Il presidente cinese Xi Jinping riceve a Pechino il leader russo Vladimir Putin per rafforzare l'alleanza.",
        "priorita": "Altissima",
